import {enabledComponent,componentDefaults} from './scene-components.js';

export function postProcessSettings(objects){let selected;for(const object of objects){const p=enabledComponent(object,'PostProcessVolume');if(object.visible!==false&&object.poolActive!==false&&p&&(!selected||p.priority>selected.priority))selected=p;}if(!selected)return null;const p={...componentDefaults('PostProcessVolume'),...selected};return p.bloomEnabled&&p.bloomStrength>0||p.colorGradingEnabled||p.vignetteEnabled&&p.vignetteIntensity>0||p.chromaticAberrationEnabled&&p.chromaticAberration>0||p.grainEnabled&&p.grainIntensity>0?p:null;}
export function packedPostProcess(p,time=0){return {grade:p?.colorGradingEnabled?[p.postExposure,1+p.contrast*.01,1+p.saturation*.01,p.hueShift*Math.PI/180]:[0,1,1,0],filter:p?.colorGradingEnabled?p.colorFilter.slice():[1,1,1,1],effects:[p?.vignetteEnabled?p.vignetteIntensity:0,p?.vignetteSmoothness??.2,p?.chromaticAberrationEnabled?p.chromaticAberration:0,p?.grainEnabled?p.grainIntensity:0],vignette:[p?.vignetteCenterX??.5,p?.vignetteCenterY??.5,p?.vignetteRounded?1:0,time],vignetteColor:p?.vignetteColor?.slice()||[0,0,0,1]};}
export const postGLSL=`
uniform vec4 hbGrade,hbFilter,hbPostEffects,hbVignette,hbVignetteColor;uniform vec2 hbPostSize;
vec3 hbGradeColor(vec3 c){c*=exp2(hbGrade.x)*hbFilter.rgb;c=max(vec3(0),(c-.18)*hbGrade.y+.18);float y=dot(c,vec3(.2126,.7152,.0722));c=mix(vec3(y),c,hbGrade.z);float a=hbGrade.w;vec3 axis=vec3(.577350269);return max(vec3(0),c*cos(a)+cross(axis,c)*sin(a)+axis*dot(axis,c)*(1.0-cos(a)));}
vec4 hbPostColor(sampler2D image,vec2 uv){vec2 delta=(uv-.5)*hbPostEffects.z*.015;vec4 c=texture2D(image,uv);if(hbPostEffects.z>0.0){c.r=texture2D(image,clamp(uv+delta,0.0,1.0)).r;c.b=texture2D(image,clamp(uv-delta,0.0,1.0)).b;}c.rgb=hbGradeColor(c.rgb);if(hbPostEffects.x>0.0){vec2 d=(uv-hbVignette.xy)*2.0;d.x*=hbVignette.z>.5?hbPostSize.x/hbPostSize.y:1.0;float f=smoothstep(1.0-max(hbPostEffects.y,.001),1.0,length(d))*hbPostEffects.x;c.rgb=mix(c.rgb,hbVignetteColor.rgb,f);}if(hbPostEffects.w>0.0){float noise=fract(sin(dot(floor(uv*hbPostSize)+floor(hbVignette.w*60.0),vec2(12.9898,78.233)))*43758.5453)-.5;c.rgb=max(vec3(0),c.rgb+noise*hbPostEffects.w*.08);}return c;}`;
